local SwageBlockMaker = {}
local PRODUCTS = {
    iron_swageblock = { name = "Železni kalup za kovanje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni kalup za kovanje za kovace." },
    bronze_swageblock = { name = "Bronast kalup za kovanje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast kalup za kovanje za kovace." },
    silver_swageblock = { name = "Srebrn kalup za kovanje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn kalup za kovanje za kovace." },
    gilded_swageblock = { name = "Pozlačen kalup za kovanje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen kalup za kovanje za kovace." },
    jewel_set_swageblock = { name = "Draguljast kalup za kovanje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast kalup za kovanje za kovace." },
    royal_sovereign_swageblock = { name = "Kraljevski suveren kalup za kovanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren kalup za kovanje z biseri za krono." },
}
local BUILDINGS = {
    swageblock_workshop = { name = "Swageblock delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    swageblock_house = { name = "Swageblock hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_swageblock_atelier = { name = "Mojstrski swageblock atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_swageblock_palace = { name = "Suverena swageblock palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SwageBlockMaker.ironStock=18; SwageBlockMaker.bronzeStock=14; SwageBlockMaker.woodStock=10; SwageBlockMaker.leatherStock=8; SwageBlockMaker.silverStock=8; SwageBlockMaker.goldStock=6; SwageBlockMaker.jewelStock=4; SwageBlockMaker.pearlStock=4
SwageBlockMaker.productStock = {}; SwageBlockMaker.buildings = {}; SwageBlockMaker.maker = nil; SwageBlockMaker.activeMaking = {}; SwageBlockMaker.totalProducts = 0; SwageBlockMaker.dayTimer = 0
function SwageBlockMaker.init() SwageBlockMaker.ironStock=18; SwageBlockMaker.bronzeStock=14; SwageBlockMaker.woodStock=10; SwageBlockMaker.leatherStock=8; SwageBlockMaker.silverStock=8; SwageBlockMaker.goldStock=6; SwageBlockMaker.jewelStock=4; SwageBlockMaker.pearlStock=4; SwageBlockMaker.productStock={}; SwageBlockMaker.buildings={}; SwageBlockMaker.maker=nil; SwageBlockMaker.activeMaking={}; SwageBlockMaker.totalProducts=0; SwageBlockMaker.dayTimer=0; print("[SwageBlockMaker] Royal Swage Block Maker System initialized (6 products, 4 buildings)") end
function SwageBlockMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SwageBlockMaker.maker={name=n or ("Kalupnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kalupnik najet: %s (spretnost: %d)",SwageBlockMaker.maker.name,s),"success") end; return true end
function SwageBlockMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SwageBlockMaker.build(id) local ok,e=SwageBlockMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SwageBlockMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SwageBlockMaker.getQualityBonus() local b=0; for _,bd in ipairs(SwageBlockMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SwageBlockMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SwageBlockMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SwageBlockMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SwageBlockMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SwageBlockMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SwageBlockMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SwageBlockMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SwageBlockMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SwageBlockMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SwageBlockMaker.buildings==0 then return false,"Potrebna kalupna delavnica" end; if not SwageBlockMaker.maker then return false,"Potreben kalupnik" end; return true end
function SwageBlockMaker.make(pt,qty) qty=qty or 1; local ok,e=SwageBlockMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SwageBlockMaker.ironStock=SwageBlockMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SwageBlockMaker.bronzeStock=SwageBlockMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SwageBlockMaker.woodStock=SwageBlockMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SwageBlockMaker.leatherStock=SwageBlockMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SwageBlockMaker.silverStock=SwageBlockMaker.silverStock-d.silverCost*qty end; if d.goldCost then SwageBlockMaker.goldStock=SwageBlockMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SwageBlockMaker.jewelStock=SwageBlockMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SwageBlockMaker.pearlStock=SwageBlockMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SwageBlockMaker.maker then t=math.max(1,t-math.floor(SwageBlockMaker.maker.skill/13)) end; table.insert(SwageBlockMaker.activeMaking,{id="swageblock_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SwageBlockMaker.completeMaking(m) local q=1.0+(SwageBlockMaker.getQualityBonus()/100); if SwageBlockMaker.maker then q=q+(SwageBlockMaker.maker.skill/140) end; q=math.min(2.5,q); SwageBlockMaker.productStock[m.productType]=(SwageBlockMaker.productStock[m.productType] or 0)+m.quantity; SwageBlockMaker.totalProducts=SwageBlockMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SwageBlockMaker.maker then SwageBlockMaker.maker.itemsMade=SwageBlockMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SwageBlockMaker.maker.skill=math.min(100,SwageBlockMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kalup izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"swageblock.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SwageBlockMaker.update(dt) if not _G.state then return end; SwageBlockMaker.dayTimer=SwageBlockMaker.dayTimer+dt; if SwageBlockMaker.dayTimer>=30 then SwageBlockMaker.dayTimer=0; for i=#SwageBlockMaker.activeMaking,1,-1 do local m=SwageBlockMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SwageBlockMaker.completeMaking(m); table.remove(SwageBlockMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SwageBlockMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SwageBlockMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SwageBlockMaker.getStats() return {ironStock=SwageBlockMaker.ironStock,bronzeStock=SwageBlockMaker.bronzeStock,woodStock=SwageBlockMaker.woodStock,leatherStock=SwageBlockMaker.leatherStock,silverStock=SwageBlockMaker.silverStock,goldStock=SwageBlockMaker.goldStock,jewelStock=SwageBlockMaker.jewelStock,pearlStock=SwageBlockMaker.pearlStock,productStock=SwageBlockMaker.productStock,numBuildings=#SwageBlockMaker.buildings,hasMaker=SwageBlockMaker.maker~=nil,makerName=SwageBlockMaker.maker and SwageBlockMaker.maker.name or "—",makerSkill=SwageBlockMaker.maker and SwageBlockMaker.maker.skill or 0,activeMaking=#SwageBlockMaker.activeMaking,totalProducts=SwageBlockMaker.totalProducts} end
return SwageBlockMaker
